import{_ as e,o,c as d,a0 as r}from"./chunks/framework.BL79I5mR.js";const p=JSON.parse('{"title":"Aceleración de Anderson del ciclo de Picard (ANDERSON_ACCEL)","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/modificaciones-motor/03-aceleracion-de-anderson.md","filePath":"es/explanation/modificaciones-motor/03-aceleracion-de-anderson.md"}'),t={name:"es/explanation/modificaciones-motor/03-aceleracion-de-anderson.md"};function n(c,a,i,l,s,m){return o(),d("div",null,[...a[0]||(a[0]=[r('<h1 id="aceleracion-de-anderson-del-ciclo-de-picard-anderson-accel" tabindex="-1">Aceleración de Anderson del ciclo de Picard (<code>ANDERSON_ACCEL</code>) <a class="header-anchor" href="#aceleracion-de-anderson-del-ciclo-de-picard-anderson-accel" aria-label="Permalink to &quot;Aceleración de Anderson del ciclo de Picard (`ANDERSON_ACCEL`)&quot;">​</a></h1><h2 id="motivacion" tabindex="-1">Motivación <a class="header-anchor" href="#motivacion" aria-label="Permalink to &quot;Motivación&quot;">​</a></h2><p>El solver de onda dinámica resuelve las ecuaciones de nodo y de enlace por <em>iteración funcional</em> (Picard / aproximaciones sucesivas): cada pasada aplica el mismo operador de actualización de carga $G$ a las últimas estimaciones de carga hasta que ningún nodo cambia más que la tolerancia de carga $\\varepsilon_H$. La iteración de punto fijo converge <em>linealmente</em>, y el factor de subrelajación $\\omega = 0.5$ que amortigua cada actualización estabiliza la iteración sin mejorar su tasa. En redes con muchos nodos fuertemente acoplados, el solver puede consumir sus 8 intentos (<code>MAX_TRIALS</code>) en casi todos los pasos de tránsito, incluso en condiciones suaves.</p><h2 id="el-metodo" tabindex="-1">El método <a class="header-anchor" href="#el-metodo" aria-label="Permalink to &quot;El método&quot;">​</a></h2><p>La aceleración de Anderson de profundidad 2 (equivalente a la actualización de Aitken) mezcla las dos salidas más recientes del operador. Sea $H_k$ la estimación de carga al entrar a la iteración $k$, el residual es</p><p>$$r_k = G(H_k) - H_k,$$</p><p>y el coeficiente de mezcla es</p><p>$$\\alpha_k = \\mathrm{clamp}!\\left( \\frac{r_k,(r_k - r_{k-1})}{(r_k - r_{k-1})^{2}},\\ 0,\\ 1\\right), \\qquad H_{k+1} = (1-\\alpha_k),G(H_k) + \\alpha_k,G(H_{k-1}).$$</p><p>El acotamiento de $\\alpha_k$ a $[0,1]$ restringe la actualización a una <em>interpolación</em> entre dos salidas del operador ya calculadas y ya acotadas; nunca se produce una carga extrapolada. La mezcla se aplica por nodo a partir del segundo intento de cada paso de tránsito.</p><h2 id="salvaguardas" tabindex="-1">Salvaguardas <a class="header-anchor" href="#salvaguardas" aria-label="Permalink to &quot;Salvaguardas&quot;">​</a></h2><ul><li><strong>Compuerta por magnitud del residual</strong>: la mezcla se aplica solo cuando $\\lvert r_k \\rvert \\le 20,\\varepsilon_H$; lejos del régimen lineal la mezcla podría sobrepasar.</li><li><strong>Cotas físicas</strong>: un tirante mezclado negativo se descarta en favor de la iteración ordinaria de Picard.</li><li><strong>Exclusión de nodos no suaves</strong>: la aceleración se omite en los nodos donde el operador $G$ es conocido no suave (véase la <a href="#salvaguardas">tabla de nodos excluidos</a> más abajo): nodos en carga bajo <code>EXTRAN</code> con continuidad <code>EXPLICIT</code> (la rama cambia en la clave), ranura dinámica activa, conductos cerca del corte de la ranura estática, vertederos u orificios en la clave, extremos de bombas (estado discreto on/off) y el borde de encharcamiento.</li><li><strong>Criterio de convergencia doble</strong>: un nodo se cuenta como convergido solo cuando tanto el residual crudo $\\lvert G(H_k) - H_k \\rvert$ como el movimiento aceptado $\\lvert H_{k+1} - H_k \\rvert$ están dentro de la tolerancia. Sin esta doble condición, una mezcla que aterrice cerca de la iteración anterior podría declarar convergencia mientras el balance de caudales sigue sin satisfacerse.</li></ul><table tabindex="0"><thead><tr><th>Condición</th><th>Cuándo</th><th>Razón</th></tr></thead><tbody><tr><td>Nodo en carga</td><td><code>SURCHARGE_METHOD EXTRAN</code> con <code>NODE_CONTINUITY EXPLICIT</code></td><td>la rama cambia en la clave</td></tr><tr><td>Ranura dinámica activa</td><td><code>SURCHARGE_METHOD DYNAMIC_SLOT</code></td><td>la geometría se reescribe por iteración</td></tr><tr><td>Cerca del corte estático</td><td><code>SURCHARGE_METHOD SLOT</code>, $0.98 \\le \\bar y/y_{\\mathrm{full}} \\le 1.02$</td><td>el ancho de ranura entra abruptamente</td></tr><tr><td>Vertedero/orificio en la clave</td><td>LGH aguas arriba $\\ge$ clave</td><td>la ecuación de caudal cambia de forma</td></tr><tr><td>Bombas</td><td>ambos nodos extremos</td><td>el estado on/off es discreto</td></tr><tr><td>Borde de encharcamiento</td><td>nodo encharcado en $d_{\\mathrm{full}}$</td><td>piso $C^0$ en el límite de encharcamiento</td></tr></tbody></table><p><em>Tabla: Nodos excluidos de la aceleración de Anderson.</em></p><p>El efecto medido: reducción de los conteos de intentos en aproximadamente 25 a 50 % por paso de tránsito en redes que de otro modo iteran hasta el límite.</p>',14)])])}const _=e(t,[["render",n]]);export{p as __pageData,_ as default};
